import { readFileSync, writeFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'
import * as prettier from 'prettier'

// Generates src/shared/api/openapi.gen.ts from contracts/openapi.yaml.
// `--check` fails instead of writing when the committed file is stale.
const spec = pathToFileURL('contracts/openapi.yaml')
const target = 'src/shared/api/openapi.gen.ts'
const header =
  '/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n'
const source = header + astToString(await openapiTS(spec))
const output = await prettier.format(source, {
  ...(await prettier.resolveConfig(target)),
  filepath: target,
})
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== output) {
    console.error(`${target} is stale. Run npm run api:types.`)
    process.exitCode = 1
  } else console.log('API types match contracts/openapi.yaml.')
} else {
  writeFileSync(target, output)
  console.log(`Wrote ${target}.`)
}
